// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * How much the coach talks. Mirrors coach-core's `CommentaryStyle`.
 */

public enum FfiCommentaryStyle {
    
    /**
     * LLM only on notable moves (inaccuracy/mistake/blunder), canned lines
     * otherwise, no opponent or game-arc commentary.
     */
    case quiet
    /**
     * Shift-triggered: silent until the game significantly shifts (eval
     * drift, mistake/blunder, forced mate), then one recap of the stretch
     * of moves that led to the swing.
     */
    case balanced
    /**
     * Full reaction to every student move; opponent commentary whenever
     * anything is worth flagging; frequent development summaries.
     */
    case chatty
}


#if compiler(>=6)
extension FfiCommentaryStyle: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiCommentaryStyle: FfiConverterRustBuffer {
    typealias SwiftType = FfiCommentaryStyle

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiCommentaryStyle {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .quiet
        
        case 2: return .balanced
        
        case 3: return .chatty
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiCommentaryStyle, into buf: inout [UInt8]) {
        switch value {
        
        
        case .quiet:
            writeInt(&buf, Int32(1))
        
        
        case .balanced:
            writeInt(&buf, Int32(2))
        
        
        case .chatty:
            writeInt(&buf, Int32(3))
        
        }
    }
}


