/**
 * How the game ended, from the student's point of view. Mirrors
 * coach-core's `GameResult`.
 */

public enum FfiGameResult {
    
    case win
    case loss
    case draw
    case aborted
}


#if compiler(>=6)
extension FfiGameResult: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiGameResult: FfiConverterRustBuffer {
    typealias SwiftType = FfiGameResult

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiGameResult {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .win
        
        case 2: return .loss
        
        case 3: return .draw
        
        case 4: return .aborted
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiGameResult, into buf: inout [UInt8]) {
        switch value {
        
        
        case .win:
            writeInt(&buf, Int32(1))
        
        
        case .loss:
            writeInt(&buf, Int32(2))
        
        
        case .draw:
            writeInt(&buf, Int32(3))
        
        
        case .aborted:
            writeInt(&buf, Int32(4))
        
        }
    }
}


