#if swift(>=5.8)
@_documentation(visibility: private)
#endif
fileprivate struct FfiConverterOptionString: FfiConverterRustBuffer {
    typealias SwiftType = String?

    public static func write(_ value: SwiftType, into buf: inout [UInt8]) {
        guard let value = value else {
            writeInt(&buf, Int8(0))
            return
        }
        writeInt(&buf, Int8(1))
        FfiConverterString.write(value, into: &buf)
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SwiftType {
        switch try readInt(&buf) as Int8 {
        case 0: return nil
        case 1: return try FfiConverterString.read(from: &buf)
        default: throw UniffiInternalError.unexpectedOptionalTag
        }
    }
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
fileprivate struct FfiConverterSequenceString: FfiConverterRustBuffer {
    typealias SwiftType = [String]

    public static func write(_ value: [String], into buf: inout [UInt8]) {
        let len = Int32(value.count)
        writeInt(&buf, len)
        for item in value {
            FfiConverterString.write(item, into: &buf)
        }
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> [String] {
        let len: Int32 = try readInt(&buf)
        var seq = [String]()
        seq.reserveCapacity(Int(len))
        for _ in 0 ..< len {
            seq.append(try FfiConverterString.read(from: &buf))
        }
        return seq
    }
}
/**
 * One game's full record at `db_path` as JSON (`{game, moves, chat}`), or
 * `None` if no such game id. Free function; see [`history_list`] for the
 * concurrency story.
 */
public func gameDetail(dbPath: String, gameId: Int64)throws  -> String?  {
    return try  FfiConverterOptionString.lift(try rustCallWithError(FfiConverterTypeFfiError_lift) {
    uniffi_coach_ffi_fn_func_game_detail(
        FfiConverterString.lower(dbPath),
        FfiConverterInt64.lower(gameId),$0
    )
})
}
/**
 * Finished games at `db_path`, newest first, as a JSON array of game rows
 * (id, started_at, ended_at, result, bot_level, opponent_kind, eco,
 * opening, acl, accuracy, est_rating, moves_judged, move_count).
 *
 * A free function (not a session method) so the History screen works
 * without touching the live session: it opens a short-lived read-only
 * connection per call — SQLite WAL lets this read run concurrently with
 * the session's write connection.
 */
public func historyList(dbPath: String, limit: UInt32, offset: UInt32)throws  -> String  {
    return try  FfiConverterString.lift(try rustCallWithError(FfiConverterTypeFfiError_lift) {
    uniffi_coach_ffi_fn_func_history_list(
        FfiConverterString.lower(dbPath),
        FfiConverterUInt32.lower(limit),
        FfiConverterUInt32.lower(offset),$0
    )
})
}
